  for (let start = 0;start < questions.length; start += 250) {
    const end = Math.min(start + 250, questions.length);
    const batchQuestions = questions.slice(start, end);
    const batchVectors = vectors.slice(start, end);
    await collection.upsert({
      ids: batchQuestions.map((q2) => `yt_q_${q2.id}`),
      embeddings: batchVectors,
      documents: batchQuestions.map((q2) => q2.document),
      metadatas: batchQuestions.map((q2, offset) => ({
        type: "knowledge",
        kind: "youtube_question",
        orgId: job.orgId,
        kbId: job.kbId,
        docId,
        source,
        title: q2.metadata.question,
        chunkIndex: start + offset,
        question_id: q2.metadata.id,
        question_type: q2.metadata.question_type,
        difficulty: q2.metadata.difficulty,
        topics: q2.metadata.topics,
        has_code: q2.metadata.has_code,
        has_options: q2.metadata.has_options,
        has_answer: q2.metadata.has_answer,
        source_platform: q2.metadata.source_platform,
        ...q2.metadata.source_url ? { source_url: q2.metadata.source_url } : {}
      }))
    });
  }
  console.info(`[DB:questions-publish] complete orgId=${job.orgId} docId=${docId} count=${questions.length} elapsedMs=${Date.now() - startedAt}`);
